"use client";

import { useState } from "react";
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon, FileText } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays, parseISO } from "date-fns";

export default function CalendarClient({ initialTasks }: { initialTasks: any[] }) {
  const [currentMonth, setCurrentMonth] = useState(new Date());

  // Task'ları tarih bazlı bir objeye dönüştürelim (Hızlı erişim için)
  const taskMap = initialTasks.reduce((acc: any, task) => {
    try {
      const data = JSON.parse(task.description || "{}");
      const dateKey = data.datum; // "2024-05-20" formatında
      if (!acc[dateKey]) acc[dateKey] = [];
      acc[dateKey].push({ ...task, data });
    } catch (e) { console.error("Data parse hatası"); }
    return acc;
  }, {});

  const renderHeader = () => (
    <div className="flex justify-between items-center mb-10 border-b border-teal-500/10 pb-6">
      <div>
        <h1 className="text-4xl font-black text-white italic tracking-tighter uppercase leading-none">Temporal Grid</h1>
        <p className="text-teal-500/50 text-[10px] font-bold tracking-[0.4em] mt-2 uppercase">{format(currentMonth, "MMMM yyyy")}</p>
      </div>
      <div className="flex gap-4">
        <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-3 border border-teal-500/20 hover:bg-teal-500/10 text-teal-500 transition-all">
          <ChevronLeft size={20} />
        </button>
        <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-3 border border-teal-500/20 hover:bg-teal-500/10 text-teal-500 transition-all">
          <ChevronRight size={20} />
        </button>
      </div>
    </div>
  );

  const renderDays = () => {
    const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
    return (
      <div className="grid grid-cols-7 mb-2">
        {days.map((day) => (
          <div key={day} className="text-[10px] font-black text-fuchsia-500 uppercase tracking-widest text-center py-2">
            {day}
          </div>
        ))}
      </div>
    );
  };

  const renderCells = () => {
    const monthStart = startOfMonth(currentMonth);
    const monthEnd = endOfMonth(monthStart);
    const startDate = startOfWeek(monthStart, { weekStartsOn: 1 });
    const endDate = endOfWeek(monthEnd, { weekStartsOn: 1 });

    const rows = [];
    let days = [];
    let day = startDate;

    while (day <= endDate) {
      for (let i = 0; i < 7; i++) {
        const formattedDate = format(day, "yyyy-MM-dd");
        const dayTasks = taskMap[formattedDate] || [];
        const isSelected = isSameDay(day, new Date());
        const isCurrentMonth = isSameMonth(day, monthStart);

        days.push(
          <div
            key={day.toString()}
            className={`min-h-[120px] border border-teal-500/5 p-2 transition-all ${
              !isCurrentMonth ? "opacity-20" : "opacity-100"
            } ${isSelected ? "bg-teal-500/5 border-teal-500/20" : "hover:bg-white/[0.02]"}`}
          >
            <span className={`text-[10px] font-mono ${isSelected ? "text-fuchsia-500 font-black" : "text-teal-500/40"}`}>
              {format(day, "d")}
            </span>
            
            <div className="mt-2 space-y-1">
              {dayTasks.map((t: any) => (
                <div key={t.id} className="text-[9px] bg-[#0E153A] border-l-2 border-fuchsia-500 p-1 truncate text-teal-100 flex items-center gap-1">
                  <div className="w-1 h-1 rounded-full bg-fuchsia-500 shadow-[0_0_5px_#d946ef]" />
                  {t.data.documentType.toUpperCase()}
                </div>
              ))}
            </div>
          </div>
        );
        day = addDays(day, 1);
      }
      rows.push(<div className="grid grid-cols-7" key={day.toString()}>{days}</div>);
      days = [];
    }
    return <div className="bg-[#0a0e17] border border-white/5">{rows}</div>;
  };

  return (
    <div className="max-w-7xl mx-auto">
      {renderHeader()}
      <div className="bg-[#0E153A]/40 backdrop-blur-xl p-4 border border-teal-500/10 rounded-xl overflow-hidden shadow-2xl">
        {renderDays()}
        {renderCells()}
      </div>
    </div>
  );
}